// Already validated and projected onto this task's fields by "Normalize Input".
const variables = $input.first().json.variables;
const chunkSize = 20;

const systemPrompt = [
  'You classify variables of a wide unit-record dataset (one row per unit, e.g. one survey respondent) into DDI-CDI component roles.',
  '',
  'Official DDI-CDI definitions:',
  '- IdentifierComponent: Role given to a represented variable in the context of a wide data structure to identify the units associated to data points.',
  '- MeasureComponent: Role given to a represented variable in the context of a data structure to hold the observed/derived values.',
  '- AttributeComponent: Role given to a represented variable in the context of a data structure to qualify observations or provide other types of supplementary information.',
  '',
  'How to apply them to this wide dataset:',
  '- IdentifierComponent: identifies the unit a row belongs to. Usually one or two variables per dataset: respondent/person/household id, case or serial number.',
  '- AttributeComponent: the time and place of the record, plus paradata and administrative information about how it was collected. Time: interview date and time, interview start/end and duration, fieldwork period, survey round or edition. Place: country, region, postcode, latitude and longitude (also imputed ones). Paradata: interviewer id, mode or language of interview, data release/version, weights, imputation or quality flags.',
  '- MeasureComponent: everything that holds an observed or derived value about the unit. Examples: survey answers, background characteristics (age, sex, education, country of birth, citizenship), scales and indices, recoded or computed variables, and linked contextual data such as weather or air quality at the respondent\'s location.',
  '',
  'Rules:',
  '- Judge by what the value itself represents, not by words in the label. "Air quality index on interview date" is a measure (the value is air quality), while "Date of interview" is an attribute (the value is the date).',
  '- Derived, recoded and linked variables are measures.',
  '- Variables giving the time or place of the record are always attributes. For anything else, when unsure between attribute and measure, choose MeasureComponent.',
  '- Use every field given for a variable together: variable_name, variable_label, variable_description, variable_source_question, variable_datatype, variable_format, variable_measure, variable_value_labels (at most the first 15 value/label pairs; variable_value_labels_total is the full count) and variable_missing_values. A missing field means it is unknown.',
  '- Return exactly one entry per variable, echoing variable_name unchanged. Return "" only if no role can be assigned at all.'
].join('\n');

const chunks = [];
for (let i = 0; i < variables.length; i += chunkSize) {
  chunks.push(variables.slice(i, i + chunkSize));
}

return chunks.map(chunk => ({
  json: {
    systemPrompt,
    userMessage: JSON.stringify(chunk, null, 2)
  }
}));

