// Collect per-chunk results.
// "Basic LLM Chain" runs with onError: continueRegularOutput, so a chunk whose
// LLM call or output parsing failed arrives here with no `output`. Emit a record
// for it instead of throwing -- one bad chunk must not take down the whole response.
const results = [];
let ok = 0;
let failed = 0;

for (const item of $input.all()) {
  const j = item.json || {};
  const chunkResults = j.output && Array.isArray(j.output.results) ? j.output.results : null;

  if (chunkResults) {
    for (const r of chunkResults) {
      results.push({ ...r, status: 'ok' });
      ok++;
    }
    continue;
  }

  // userMessage is JSON.stringify(chunk), so the variable names are recoverable.
  let names = [];
  try {
    const chunk = JSON.parse(j.userMessage || '[]');
    names = Array.isArray(chunk) ? chunk.map((v) => v.variable_name || '') : [];
  } catch (e) { /* leave empty */ }

  const err = j.error;
  const message = (err && (err.message || err.description)) ||
    'LLM chain produced no parsable output';

  if (names.length === 0) names = [''];
  for (const name of names) {
    results.push({ variable_name: name, component_role: '', status: 'failed', error: message });
    failed++;
  }
}

return [{ json: { results, ok, failed, total: results.length } }];

// Normalize Input -- shared by every variable-enrichment workflow.
// Contract: schemas/variable_input.py (VariableInput). Generated by
// `python schemas/variable_input.py --node <task>`; edit the template, not the node.
// FIELDS is the subset of VariableInput this task's LLM sees (TASK_FIELDS["role"]).
const FIELDS = ["variable_label", "variable_description", "variable_source_question", "variable_datatype", "variable_format", "variable_measure", "variable_value_labels", "variable_value_labels_total", "variable_missing_values"];
const MAX_VALUE_LABELS = 15;
const LEGACY = { label: 'variable_label', description: 'variable_description', source_question: 'variable_source_question' };

// Webhook puts the payload under body; the Execute Workflow Trigger does not.
const input = $input.first().json;
const variables = input.body ? input.body.variables : input.variables;

const fail = (error) => [{ json: { valid: false, error } }];
if (!Array.isArray(variables) || variables.length === 0) {
  return fail('Expected a non-empty "variables" array of VariableInput objects.');
}

const isEmpty = (v) => v === null || v === undefined || v === '' || (Array.isArray(v) && v.length === 0);
const out = [];

for (const [i, v] of variables.entries()) {
  if (!v || typeof v !== 'object' || Array.isArray(v)) return fail(`variables[${i}] is not an object.`);
  if (typeof v.variable_name !== 'string' || !v.variable_name) return fail(`variables[${i}] is missing variable_name.`);

  const legacy = Object.keys(LEGACY).filter((k) => k in v);
  if (legacy.length) {
    const hint = legacy.map((k) => `${k} -> ${LEGACY[k]}`).join(', ');
    return fail(`variables[${i}] (${v.variable_name}) uses legacy keys; rename ${hint}.`);
  }

  const labels = (Array.isArray(v.variable_value_labels) ? v.variable_value_labels : [])
    .filter((l) => l && l.value !== undefined && l.label !== undefined)
    .map((l) => ({ value: String(l.value), label: String(l.label) }));
  const full = {
    ...v,
    variable_value_labels: labels.slice(0, MAX_VALUE_LABELS),
    variable_value_labels_total: labels.length ? (v.variable_value_labels_total ?? labels.length) : null,
  };

  const item = { variable_name: v.variable_name };
  for (const f of FIELDS) {
    if (!isEmpty(full[f])) item[f] = full[f];
  }
  out.push(item);
}

return [{ json: { valid: true, variables: out } }];
